/// A proc called once per entry of `calls`, its state carried from each call to the next.
pub fn call_seq(name: &str, calls: &[Vec<f64>]) -> Option<Vec<Vec<f64>>> {
    let mut outs = Vec::new();
    match name {
        _ => return None,
    }
    Some(outs)
}
